// Platform-wide economic parameters contract (BLOCKCHAIN_ECONOMICS §4–§8, §12).
//
// Editable in place, address stable: `update_params` is admin-gated and MUTATES
// STORAGE (no redeploy), so every other contract / off-chain node can hard-pin
// this address. Each update is bounds-validated on-chain (mirroring the §12
// invariants), emits a `ParamsUpdated` log, and rejects unauthorized senders.
// The admin is a single configurable address today, designed to later point at a
// multisig (rotate via `update_admin`).

import "common"
import "global_params_types"

contract GlobalParams {
    storage: GlobalParamsStorage
    incomingMessages: AllowedMessageToGlobalParams
}

type AllowedMessageToGlobalParams =
    | UpdateParams
    | UpdateAdmin
    | SetBlocklisted
    | AnnounceCode
    | UpgradeCode
    | CancelCode

fun onBouncedMessage(_in: InMessageBounced) {}

fun onInternalMessage(in: InMessage) {
    val msg = lazy AllowedMessageToGlobalParams.fromSlice(in.body);

    match (msg) {
        // Admin-gated, in-place parameter update. Address is unchanged because we
        // setData (mutate) rather than redeploy.
        UpdateParams => {
            var storage = lazy GlobalParamsStorage.load();
            assert (in.senderAddress == storage.admin) throw ErrCode.NOT_ADMIN;

            // Bounds-validate on-chain BEFORE persisting (reject bad updates).
            val newParams = msg.params.load();
            validateEcoParams(newParams);

            storage.feeRecipient = msg.feeRecipient;
            storage.params = msg.params;
            // Monotonic bump on EVERY successful update so jobs can pin the
            // exact params set in force. The admin never controls this counter.
            storage.paramsVersion += 1;
            storage.save();

            // Emit a "params updated" event for off-chain indexers, carrying the
            // new version so they can track which params set is now live.
            val ev = createExternalLogMessage({
                dest: ExtOutLogBucket { topic: EVENT_PARAMS_UPDATED },
                body: ParamsUpdated {
                    queryId: msg.queryId,
                    version: storage.paramsVersion,
                    platformFeeBps: newParams.platformFeeBps,
                    minStake: newParams.minStake,
                },
            });
            ev.send(SEND_MODE_REGULAR);
        }

        // Admin rotation (single key -> multisig handoff). Admin-gated.
        UpdateAdmin => {
            var storage = lazy GlobalParamsStorage.load();
            assert (in.senderAddress == storage.admin) throw ErrCode.NOT_ADMIN;
            storage.admin = msg.newAdmin;
            storage.save();
        }

        // Governance blocklist update (anti-abuse). Admin-gated, mutates storage
        // in place. Sets the subject blocked (1) or clears it (0).
        SetBlocklisted => {
            var storage = lazy GlobalParamsStorage.load();
            assert (in.senderAddress == storage.admin) throw ErrCode.NOT_ADMIN;
            storage.blocklist.set(msg.subject, (msg.blocked ? 1 : 0) as uint1);
            storage.save();
        }

        // D2 step 1/2 — ANNOUNCE: commit to the successor code's hash + start the
        // timelock clock. Admin-gated. Re-announcing resets the clock.
        AnnounceCode => {
            var storage = lazy GlobalParamsStorage.load();
            assert (in.senderAddress == storage.admin) throw ErrCode.NOT_ADMIN;
            storage.pendingCodeHash = msg.newCodeHash;
            storage.pendingCodeAt = blockchain.now() as uint32;
            storage.save();
        }

        // D2 step 2/2 — APPLY the announced IN-PLACE code upgrade (§12.1). Swaps
        // this contract's CODE via TVM `SETCODE` while the ADDRESS and all STORAGE
        // stay intact (we never redeploy; we never wipe data), so adding a new
        // EcoParams field/getter no longer forces a move to a new address.
        // `SETCODE` is POSTPONED: the new code takes effect only after this
        // transaction terminates successfully. D2 hardening: this is now
        // TIMELOCKED — rejected before `pendingCodeAt + upgradeDelay`, and only the
        // exact announced code (hash-committed) may be applied, so a single key can
        // no longer instantly swap protocol-wide code. The monotonic `codeVersion`
        // is bumped by the contract (never set by the admin).
        UpgradeCode => {
            var storage = lazy GlobalParamsStorage.load();
            assert (in.senderAddress == storage.admin) throw ErrCode.NOT_ADMIN;
            assert (storage.pendingCodeHash != 0) throw ErrCode.NO_PENDING_UPGRADE;
            assert (msg.newCode.hash() == storage.pendingCodeHash) throw ErrCode.UPGRADE_CODE_MISMATCH;
            val readyAt = storage.pendingCodeAt + storage.upgradeDelay;
            assert (blockchain.now() >= readyAt) throw ErrCode.UPGRADE_TIMELOCK_ACTIVE;

            // Queue the code swap (effective after this run) and persist the
            // bumped version + cleared pending state. Storage layout is unchanged
            // here; a future migration would be applied to `storage` BEFORE save()
            // in this same handler (the OLD code controls the layout until the
            // postponed SETCODE lands).
            contract.setCodePostponed(msg.newCode);
            storage.codeVersion += 1;
            storage.pendingCodeHash = 0;
            storage.pendingCodeAt = 0;
            storage.save();

            val ev = createExternalLogMessage({
                dest: ExtOutLogBucket { topic: EVENT_CODE_UPGRADED },
                body: CodeUpgraded {
                    queryId: msg.queryId,
                    codeVersion: storage.codeVersion,
                    codeHash: msg.newCode.hash(),
                },
            });
            ev.send(SEND_MODE_REGULAR);
        }

        // D2 — abort a pending announcement (admin-gated safety valve).
        CancelCode => {
            var storage = lazy GlobalParamsStorage.load();
            assert (in.senderAddress == storage.admin) throw ErrCode.NOT_ADMIN;
            assert (storage.pendingCodeHash != 0) throw ErrCode.NO_PENDING_UPGRADE;
            storage.pendingCodeHash = 0;
            storage.pendingCodeAt = 0;
            storage.save();
        }

        else => {
            assert (in.body.isEmpty()) throw ErrCode.INVALID_OP;
        }
    }
}

// ---------------------------------------------------------------------------
// Getters
// ---------------------------------------------------------------------------

get fun get_params(): GlobalParamsView {
    val storage = lazy GlobalParamsStorage.load();
    return {
        admin: storage.admin,
        feeRecipient: storage.feeRecipient,
        params: storage.params,
        paramsVersion: storage.paramsVersion,
    };
}

// Monotonic params version/seqno — the single authoritative value a job binds
// to so all parties agree which params it ran under. Read cheaply via RPC
// (the off-chain coordinator pins this into each job record / escrow).
get fun get_params_version(): int {
    val storage = lazy GlobalParamsStorage.load();
    return storage.paramsVersion;
}

// Monotonic CODE version/seqno — bumped on every successful in-place
// `upgrade_code` (§12.1). 0 = original deployed code (never upgraded). Distinct
// from `paramsVersion`: this tracks CODE swaps (TVM SETCODE) at a STABLE
// address, that one tracks data/param edits. Off-chain code can read this to
// learn which contract code is live without the address ever changing.
get fun get_code_version(): int {
    val storage = lazy GlobalParamsStorage.load();
    return storage.codeVersion;
}

// D2: the pending timelocked code upgrade (announced hash, when, and the earliest
// applyable ts = announce + upgradeDelay). All 0 when none pending — so the
// ecosystem can observe (and react to) a queued protocol-wide code change.
get fun get_pending_upgrade(): GlobalParamsUpgradeView {
    val storage = lazy GlobalParamsStorage.load();
    val readyAt = storage.pendingCodeAt == 0 ? 0 : storage.pendingCodeAt + storage.upgradeDelay;
    return {
        codeVersion: storage.codeVersion,
        pendingCodeHash: storage.pendingCodeHash,
        pendingAt: storage.pendingCodeAt,
        readyAt: readyAt as uint32,
    };
}

// Scalar policy getters (single-int read path for the off-chain `run_get_int`
// RPC seam): the ecosystem-wide values paid jobs read as authoritative,
// overriding local defaults. Each loads the child `EcoParams` cell.
get fun get_platform_fee_bps(): int {
    return GlobalParamsStorage.load().params.load().platformFeeBps;
}

get fun get_participation_commission_bps(): int {
    return GlobalParamsStorage.load().params.load().participationCommissionBps;
}

get fun get_slash_failed_commitment_bps(): int {
    return GlobalParamsStorage.load().params.load().slashFailedCommitmentBps;
}

get fun get_attempt_deadline_ms(): int {
    return GlobalParamsStorage.load().params.load().attemptDeadlineMs;
}

get fun get_progress_interval_ms(): int {
    return GlobalParamsStorage.load().params.load().progressIntervalMs;
}

get fun get_progress_stall_mult(): int {
    return GlobalParamsStorage.load().params.load().progressStallMult;
}

get fun get_admin(): address {
    val storage = lazy GlobalParamsStorage.load();
    return storage.admin;
}

get fun get_fee_recipient(): address {
    val storage = lazy GlobalParamsStorage.load();
    return storage.feeRecipient;
}

// Whether a subject (256-bit account hash) is on the governance blocklist.
get fun get_blocklisted(subject: int): bool {
    val storage = lazy GlobalParamsStorage.load();
    val found = storage.blocklist.get(subject as uint256);
    if (!found.isFound) {
        return false;
    }
    return found.loadValue() == 1;
}

// Shared error codes, opcodes and constants for the duckdb-p2p settlement layer.
//
// These contracts implement the *paid* path of the economic layer described in
// `docs/BLOCKCHAIN_ECONOMICS.md`. Free jobs never touch any of this code — the
// requester runs them through the off-chain coordinator with the `NoopSettlement`
// path and there is zero on-chain interaction (see §8.2 "Free vs paid path").
//
// Design constraints honoured here (BLOCKCHAIN_ECONOMICS §1, §8):
//   * sharded per-node state (no global contract): one StakeVault per node,
//     one JobEscrow per job — never a single hot contract.
//   * non-custodial: release is governed entirely by contract code (quorum
//     result-hash, challenge window, unbonding cooldown), never a platform key.
//   * defensive TON style: explicit gas floors, bounce-safe, carry-value.
// ---------------------------------------------------------------------------
// Error codes — a typed `enum` (Tolk production guidance) instead of loose
// `const`s, so every `throw`/`assert` is checked against a single named set and
// a typo can't silently invent a new code. The backing type is `int32` (the TVM
// exit-code width); the numeric values are FROZEN — they are the contract ABI
// that off-chain code and tests assert against — so they are kept verbatim.
// Reference members as `ErrCode.NOT_OWNER`, etc.
// ---------------------------------------------------------------------------

enum ErrCode: int32 {
    // Jetton / receipt wallet
    NOT_OWNER = 132            // sender is not the contract owner
    NOT_FROM_MASTER = 133      // sender is not the jetton master (vault)
    NOT_VALID_WALLET = 134     // sender is not a legitimate sibling receipt wallet
    UNAUTHORIZED_BURN = 135    // burn notification not from the owner's wallet
    BALANCE_NEGATIVE = 136     // resulting balance would be negative
    NOT_ENOUGH_GAS = 137       // attached value too small to cover the operation
    RECEIPT_LOCKED = 138       // stake-receipt jetton is non-transferable (anti-exit)
    INVALID_OP = 0xffff        // unknown opcode

    // Stake vault
    NOT_SLASHER = 200          // sender is not the authorized slasher (dispute contract)
    NOTHING_TO_UNBOND = 201    // unbond requested but no eligible stake
    UNBOND_IN_PROGRESS = 202   // a prior unbond is still cooling down
    COOLDOWN_NOT_ELAPSED = 203 // withdraw before the unbonding cooldown finished
    NO_UNBONDING = 204         // withdraw with nothing in the unbonding bucket
    KEEPER_TOO_EARLY = 205     // keeper withdraw before the owner-grace window
    SLASH_EXCEEDS_STAKE = 206  // slash amount larger than slashable stake
    INVALID_SPLIT = 207        // slash split bps do not sum to 10000
    // Timelocked governance code upgrade (§8.6) — preserves the non-custodial
    // guarantee: an announced code swap can only be APPLIED after a delay >= the
    // unbonding window, so stakers can exit before any new code takes effect.
    NO_PENDING_UPGRADE = 208   // apply/cancel with nothing announced
    UPGRADE_TIMELOCK_ACTIVE = 209 // apply before the timelock delay elapsed
    UPGRADE_CODE_MISMATCH = 210 // applied code != the announced (hash-committed) code

    // Escrow
    ESCROW_NOT_FUNDED = 220    // escrow opened without the requester's max-bid B
    NOT_REQUESTER = 221        // settle/refund by someone other than the requester
    NOT_ARBITER = 222          // settle by someone other than the bound arbiter
    HASH_MISMATCH = 223        // provided result hash != the committed quorum hash
    ALREADY_SETTLED = 224      // escrow already released
    TIMEOUT_NOT_REACHED = 225  // refund-on-timeout before the deadline
    PAYOUT_EXCEEDS_ESCROW = 226 // requested payout exceeds the locked escrow B

    // Record anchor / dispute
    BAD_PREV_ROOT = 240        // submitted root does not chain to the stored prev_root
    EPOCH_REGRESSION = 241     // epoch did not advance monotonically
    INSUFFICIENT_ANCHOR_STAKE = 242 // keeper stake-weight below the acceptance threshold
    BAD_INCLUSION_PROOF = 243  // Merkle inclusion proof does not reproduce the root
    DISPUTE_BOND_TOO_LOW = 244 // challenger bond below the configured minimum
    NO_SUCH_DISPUTE = 245      // verdict for an unknown dispute id
    NOT_VERDICT_AUTHORITY = 246 // verdict from a non-authoritative source
    // --- Appended (security hardening; never renumber the frozen codes above) ---
    DISPUTE_NOT_OPEN = 247     // resolve a dispute that is not in the open (0) state (double-resolve)
    UNKNOWN_EPOCH = 248        // dispute references an epoch that was never anchored
    PROOF_TOO_DEEP = 249       // Merkle proof exceeds the max depth bound (gas-griefing guard)
    NOT_ANCHOR_KEEPER = 250    // root submitted by an address that is not the authorized keeper
    ZERO_ROOT = 251            // refuse anchoring an empty / all-zero root
    BOND_FLOOR_TOO_LOW = 252   // configured disputeBondMin is below the on-chain floor (> 0)

    // Global params (platform-wide config)
    NOT_ADMIN = 260            // sender is not the configured admin (or multisig)
    PARAMS_OUT_OF_BOUNDS = 261 // proposed params violate a §12 invariant

    // --- Appended: escrow / vault payout-authorization + bounce hardening ------
    NOT_OWNER_SIG = 280        // settle split not authorized by the fund-owner (requester) commitment
    SETTLE_POLICY_MISMATCH = 281 // settle payload does not match the requester's pre-committed policy hash
    TOO_MANY_PARTICIPANTS = 282  // participants map exceeds the on-chain payout bound (action/gas safety)
    UPGRADE_NOT_AUTHORITY = 283  // upgrade announced/applied by a non-upgrade-authority (separated from slasher)
    BAD_BOUNTY_BPS = 284         // keeperBountyBps out of [0, BPS_DENOM] (config sanity)
}

// ---------------------------------------------------------------------------
// Opcodes — keep TEP-74 standard values verbatim for ecosystem interop.
// ---------------------------------------------------------------------------

// TEP-74 jetton standard
const OP_JETTON_TRANSFER = 0x0f8a7ea5
const OP_JETTON_TRANSFER_INTERNAL = 0x178d4519
const OP_JETTON_NOTIFICATION = 0x7362d09c
const OP_JETTON_EXCESSES = 0xd53276db
const OP_JETTON_BURN = 0x595f07bc
const OP_JETTON_BURN_NOTIFICATION = 0x7bdd97de
const OP_PROVIDE_WALLET_ADDRESS = 0x2c76b973
const OP_TAKE_WALLET_ADDRESS = 0xd1735400

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const MIN_TONS_FOR_STORAGE = ton("0.05")
const BPS_DENOM = 10000 // basis-points denominator for splits/fractions

// Status bit flags for the stake-receipt wallet.
const RECEIPT_STATUS_LOCKED = 1 // bit 0: outgoing transfers locked (default)

// Max Merkle inclusion-proof depth the on-chain verifier will walk before
// aborting (A4: an attacker-supplied proof chain is otherwise unbounded → gas
// griefing). 32 levels = up to 2^32 leaves per epoch, far beyond any realistic
// epoch batch, so this never rejects an honest proof.
const MAX_MERKLE_PROOF_DEPTH = 32

// On-chain floor for the dispute bond minimum (A5): a config that sets
// disputeBondMin below this is rejected at deploy/validate time so near-zero-bond
// griefing is impossible. 0.01 TON is a token but non-trivial anti-spam cost.
const MIN_DISPUTE_BOND_FLOOR = ton("0.01")

// Upper bound on the number of agreeing non-winners paid in a single settle
// action phase (B4): bounding the participants map keeps the settle within the
// TVM action/gas limit so a payout can never be partial. 32 covers the realistic
// committee size (N_max=10) with wide headroom.
const MAX_SETTLE_PARTICIPANTS = 32

// Storage, messages and on-chain bounds validation for the platform-wide
// `GlobalParams` contract (BLOCKCHAIN_ECONOMICS §4–§8, §12).
//
// This is the ONE ecosystem-wide contract: it holds the economic parameters
// every other contract / off-chain node reads (fees, surcharge, participation
// commission, slash %s + split, min-stake tiers, stake cap, unbonding /
// challenge windows, default selection N/quorum/checksum, ranking weights, fee
// recipient). It is **editable in place**: an admin-gated `update_params`
// MUTATES STORAGE — there is no redeploy — so the contract **address is stable**
// and other contracts can hard-reference it. The admin is a single configurable
// address today but is designed to later point at a multisig (admin rotation via
// `update_admin`).
//
// Every update is **bounds-validated on-chain**, mirroring the §12 cross-field
// invariants enforced off-chain in `crates/config` (so the chain is the source
// of truth and cannot be driven into an inconsistent state even by the admin).

import "common"

const OP_UPDATE_PARAMS = 0x47504101 // "GPA" 01
const OP_UPDATE_ADMIN = 0x47504102  // "GPA" 02
const OP_SET_BLOCKLISTED = 0x47504103 // "GPA" 03 — governance blocklist (anti-abuse)
const OP_UPGRADE_CODE = 0x47504104  // "GPA" 04 — admin-gated, TIMELOCKED apply (step 2)
const OP_ANNOUNCE_CODE = 0x47504105 // "GPA" 05 — admin-gated upgrade announce (step 1)
const OP_CANCEL_CODE = 0x47504106   // "GPA" 06 — admin-gated upgrade cancel

// Log topic for the emitted "code upgraded" event (external-out message), so
// off-chain indexers can watch in-place code upgrades without parsing internals.
const EVENT_CODE_UPGRADED = 0x6770_7570 + 1 // "gpup"+1

// Log topic for the emitted "params updated" event (external-out message), so
// off-chain indexers can watch parameter changes without parsing internals.
const EVENT_PARAMS_UPDATED = 0x6770_7570 // "gpup"

// Bulk economic parameters, kept in a child cell (bit budget). All fractions are
// basis points (bps, /10000); stakes are coins; windows are seconds; selection
// counts are small ints; ranking weights are bps.
struct EcoParams {
    platformFeeBps: uint16
    surchargeBps: uint16
    participationCommissionBps: uint16   // κ — must be small (<= 1000 bps = 10%)
    slashWrongBps: uint16
    slashCheatBps: uint16
    slashDowntimeBps: uint16
    slashEquivocationBps: uint16
    splitChallengerBps: uint16
    splitRedundancyBps: uint16
    splitBurnBps: uint16
    splitTreasuryBps: uint16
    minStake: coins
    minStakeInternal: coins
    minStakeSensitive: coins
    stakeCap: coins
    unbondingSecs: uint32
    challengeWindowSecs: uint32
    nPublic: uint8
    nDefault: uint8
    nMax: uint8
    quorum: uint8
    checksumMin: uint8
    wQualityBps: uint16
    wStakeBps: uint16
    wPriceBps: uint16
    // --- Resilience / fairness gating (ARCHITECTURE §8/§11) ----------------
    // These are the ecosystem-wide resilience knobs that affect DISPUTE
    // FAIRNESS, so all parties must agree on the values a job ran under (they
    // are additive — appended after the original economic params to keep the
    // cell layout backward-compatible).
    //
    // Fine (bps of bonded stake) for a broken commitment to PAID work: a
    // provider that accepted/bid then failed to deliver a valid result by the
    // deadline while the job was demonstrably feasible (§8.3).
    slashFailedCommitmentBps: uint16
    // Requester per-attempt deadline (ms): an attempt going silent past this is
    // treated as inconclusive (job-fault, NO provider penalty). The boundary
    // between "inconclusive" and "broken commitment" — hence on-chain.
    attemptDeadlineMs: uint32
    // Expected progress/heartbeat interval (ms) the host streams at; with
    // progressStallMult it derives the stall timeout that gates a failed
    // commitment.
    progressIntervalMs: uint32
    // Stall-timeout multiplier: an attempt is declared stalled (re-dispatched)
    // after progressIntervalMs * progressStallMult with no heartbeat.
    progressStallMult: uint8
}

struct GlobalParamsStorage {
    admin: address          // gate for update_params / update_admin (→ multisig later)
    feeRecipient: address   // platform fee destination (configurable, §8.2)
    params: Cell<EcoParams> // the bulk params child cell
    // Governance blocklist (ARCHITECTURE "Abuse resistance"): admin-gated, for
    // egregious PROVABLE cases. Keyed by the subject's 256-bit account hash;
    // value 1 = blocked. Nodes may optionally consult this on-chain list, but
    // each still decides independently (it is an additional source, not a
    // central authority that forces refusal).
    blocklist: map<uint256, uint1>
    // Monotonic parameters version/seqno. Bumped by the contract on EVERY
    // successful `update_params` (the admin never sets it directly), so a job
    // can pin the EXACT params set it ran under for settlement / dispute
    // resolution. Appended last → additive, address-stable layout change.
    paramsVersion: uint32
    // Monotonic CODE version/seqno (separate from `paramsVersion`). Bumped by the
    // contract on EVERY successful in-place `upgrade_code` (admin never sets it
    // directly). This is the in-place upgradeability win (§12.1): the CODE can be
    // replaced via TVM `SETCODE` WITHOUT changing the contract address or losing
    // storage, so adding a field/getter no longer forces a redeploy to a new
    // address. Appended last (additive). 0 = original deployed code (never
    // upgraded). Storage-migration rule: keep storage changes additive and
    // append new fields LAST; new code reads the existing layout (older fields
    // unchanged), and a real layout migration would be staged inside the
    // `upgrade_code` handler (the OLD code can `setData()` the migrated layout in
    // the same tx, because `SETCODE` is postponed to after this run completes).
    codeVersion: uint32
    // D2: TIMELOCKED code-upgrade state. A single-key INSTANT SETCODE is a
    // protocol-wide instant-compromise vector (this contract is hard-pinned by
    // every other contract/node), so code upgrades follow the StakeVault
    // announce → wait(upgradeDelay) → apply discipline with a code-hash
    // commitment. `pendingCodeHash`/`pendingCodeAt` are 0 when nothing is
    // announced; `apply` is rejected before `pendingCodeAt + upgradeDelay` and
    // unless the applied code's hash matches the announced one. Appended last
    // (additive). `upgradeDelay` is configurable (seconds) and validated > 0.
    upgradeDelay: uint32
    pendingCodeHash: uint256
    pendingCodeAt: uint32
}

fun GlobalParamsStorage.load(): GlobalParamsStorage {
    return GlobalParamsStorage.fromCell(contract.getData());
}

fun GlobalParamsStorage.save(self) {
    contract.setData(self.toCell());
}

// Admin-gated parameter update. Mutates storage in place (no redeploy → address
// unchanged). `feeRecipient` and the full `params` cell are replaced atomically.
struct (0x47504101) UpdateParams {
    queryId: uint64
    feeRecipient: address
    params: Cell<EcoParams>
}

// Admin rotation (e.g. hand off to a multisig once one is deployed).
struct (0x47504102) UpdateAdmin {
    queryId: uint64
    newAdmin: address
}

// Admin-gated governance blocklist update (anti-abuse). `subject` is the 256-bit
// account hash of the actor; `blocked = true` adds it, `false` clears it.
struct (0x47504103) SetBlocklisted {
    queryId: uint64
    subject: uint256
    blocked: bool
}

// D2 step 1/2 — ANNOUNCE the successor code (by its cell hash). Admin-gated.
// Records the hash + now; re-announcing overwrites and RESETS the timelock clock.
// Publicly observable via `get_pending_upgrade` so the ecosystem can react.
struct (0x47504105) AnnounceCode {
    queryId: uint64
    newCodeHash: uint256
}

// D2 step 2/2 — APPLY the announced code (§12.1). Replaces this contract's CODE
// via TVM `SETCODE` (postponed) WITHOUT changing the address or touching storage.
// Admin-gated, allowed only after `pendingCodeAt + upgradeDelay`, and only if
// `newCode.hash() == pendingCodeHash` (commit-then-reveal, no bait-and-switch).
// `codeVersion` is bumped by the contract (the admin never sets it directly).
struct (0x47504104) UpgradeCode {
    queryId: uint64
    newCode: cell
}

// D2 — abort a pending code-upgrade announcement (admin-gated safety valve).
struct (0x47504106) CancelCode {
    queryId: uint64
}

// Emitted as an external-out log on every successful in-place code upgrade.
// Carries the new monotonic `codeVersion` + the upgraded code's cell hash so
// off-chain indexers can track which code is now live at this (stable) address.
struct CodeUpgraded {
    queryId: uint64
    codeVersion: uint32
    codeHash: uint256
}

// Emitted as an external-out log on every successful update. Carries the new
// monotonic `version` so off-chain indexers can track which params set is live.
struct ParamsUpdated {
    queryId: uint64
    version: uint32
    platformFeeBps: uint16
    minStake: coins
}

// Getter shape returned by `get_params`.
struct GlobalParamsView {
    admin: address
    feeRecipient: address
    params: Cell<EcoParams>
    paramsVersion: uint32
}

// D2: getter shape for `get_pending_upgrade`. `pendingCodeHash`/`pendingAt` are 0
// when nothing is announced; `readyAt` is the unix ts the announced upgrade
// becomes applyable (`pendingAt + upgradeDelay`, 0 when none).
struct GlobalParamsUpgradeView {
    codeVersion: uint32
    pendingCodeHash: uint256
    pendingAt: uint32
    readyAt: uint32
}

// On-chain bounds validation, mirroring the §12 cross-field invariants enforced
// off-chain by `EconomicsConfig::validate`. Throws ErrCode.PARAMS_OUT_OF_BOUNDS on
// any violation so a bad admin update is rejected and storage stays consistent.
fun validateEcoParams(p: EcoParams) {
    // All bps fractions within [0, 10000].
    assert (p.platformFeeBps <= BPS_DENOM) throw ErrCode.PARAMS_OUT_OF_BOUNDS;
    assert (p.surchargeBps <= BPS_DENOM) throw ErrCode.PARAMS_OUT_OF_BOUNDS;
    assert (p.slashWrongBps <= BPS_DENOM) throw ErrCode.PARAMS_OUT_OF_BOUNDS;
    assert (p.slashCheatBps <= BPS_DENOM) throw ErrCode.PARAMS_OUT_OF_BOUNDS;
    assert (p.slashDowntimeBps <= BPS_DENOM) throw ErrCode.PARAMS_OUT_OF_BOUNDS;
    assert (p.slashEquivocationBps <= BPS_DENOM) throw ErrCode.PARAMS_OUT_OF_BOUNDS;
    assert (p.wQualityBps <= BPS_DENOM) throw ErrCode.PARAMS_OUT_OF_BOUNDS;
    assert (p.wStakeBps <= BPS_DENOM) throw ErrCode.PARAMS_OUT_OF_BOUNDS;
    assert (p.wPriceBps <= BPS_DENOM) throw ErrCode.PARAMS_OUT_OF_BOUNDS;
    // Failed-commitment slash is a stake fraction, so it too is in [0, 10000].
    assert (p.slashFailedCommitmentBps <= BPS_DENOM) throw ErrCode.PARAMS_OUT_OF_BOUNDS;

    // κ (participation commission) must be small: <= 10% (§4.2).
    assert (p.participationCommissionBps <= 1000) throw ErrCode.PARAMS_OUT_OF_BOUNDS;

    // Resilience gating must be coherent: a positive progress interval and a
    // non-zero stall multiplier, else the stall timeout would be ill-defined.
    assert (p.progressIntervalMs >= 1) throw ErrCode.PARAMS_OUT_OF_BOUNDS;
    assert (p.progressStallMult >= 1) throw ErrCode.PARAMS_OUT_OF_BOUNDS;

    // Slash split must sum to exactly 100%.
    val splitSum = p.splitChallengerBps + p.splitRedundancyBps + p.splitBurnBps + p.splitTreasuryBps;
    assert (splitSum == BPS_DENOM) throw ErrCode.PARAMS_OUT_OF_BOUNDS;

    // Per-class min-stake monotonicity + cap >= min.
    assert (p.minStakeSensitive >= p.minStakeInternal) throw ErrCode.PARAMS_OUT_OF_BOUNDS;
    assert (p.minStakeInternal >= p.minStake) throw ErrCode.PARAMS_OUT_OF_BOUNDS;
    assert (p.stakeCap >= p.minStake) throw ErrCode.PARAMS_OUT_OF_BOUNDS;

    // Unbonding must outlast the challenge window (§8.4).
    assert (p.unbondingSecs >= p.challengeWindowSecs) throw ErrCode.PARAMS_OUT_OF_BOUNDS;

    // Selection ordering: n_max >= n_default >= n_public >= checksum_min >= 1, and
    // a sane quorum (1 <= quorum <= n_default).
    assert (p.checksumMin >= 1) throw ErrCode.PARAMS_OUT_OF_BOUNDS;
    assert (p.nPublic >= p.checksumMin) throw ErrCode.PARAMS_OUT_OF_BOUNDS;
    assert (p.nDefault >= p.nPublic) throw ErrCode.PARAMS_OUT_OF_BOUNDS;
    assert (p.nMax >= p.nDefault) throw ErrCode.PARAMS_OUT_OF_BOUNDS;
    assert (p.quorum >= 1 && p.quorum <= p.nDefault) throw ErrCode.PARAMS_OUT_OF_BOUNDS;
}
